@_core.enable_ki_protection
@_core.enable_ki_protection
def repark(self, new_lot: ParkingLot, *, count: (int | float)=1) ->None:

args.new_string:
if not isinstance(new_lot, ParkingLot):
    raise TypeError("new_lot must be a ParkingLot")

# If the current lot is broken, its parked tasks have already been
# rescheduled with an error, so there is nothing to move.
if self.broken_by:
    return

# If the new lot is broken, wake up the tasks with an error instead of
# parking them in a lot that will never unpark them.
if new_lot.broken_by:
    tasks = list(self._pop_several(count))
    for task in tasks:
        _core.reschedule(
            task,
            outcome.Error(
                _core.BrokenResourceError(
                    f"Parking lot broken by {new_lot.broken_by}",
                ),
            ),
        )
    return

for task in self._pop_several(count):
    new_lot._parked[task] = None
    task.custom_sleep_data = new_lot
